   285	
   286	/*=========================================================================
   287	** Private functions.
   288	*/
   289	
   290	static int
   291	wav_read_header (SF_PRIVATE *psf, int *blockalign, int *framesperblock)
   292	{       WAVLIKE_PRIVATE *wpriv ;
   293	        WAV_FMT         *wav_fmt ;
   294	        FACT_CHUNK      fact_chunk ;
   295	        uint32_t        marker, chunk_size = 0, RIFFsize = 0, done = 0 ;
   296	        int                     parsestage = 0, error, format = 0 ;
   297	
   298	        if (psf->is_pipe == 0 && psf->filelength > SF_PLATFORM_S64 (0xffffffff))
   299	                psf_log_printf (psf, "Warning : filelength > 0xffffffff. This is bad!!!!\n") ;
   300	
   301	        if ((wpriv = psf->container_data) == NULL)
   302	                return SFE_INTERNAL ;
   303	        wav_fmt = &wpriv->wav_fmt ;
   304	
   305	        /* Set position to start of file to begin reading header. */
   306	        psf_binheader_readf (psf, "pmj", 0, &marker, -4) ;
   307	        psf->header.indx = 0 ;
   308	
   309	        /* RIFX signifies big-endian format for all header and data  to prevent
   310	        ** lots of code copying here, we'll set the psf->rwf_endian flag once here,
   311	        ** and never specify endian-ness for all other header ops/
   312	        */
   313	        psf->rwf_endian = (marker == RIFF_MARKER) ? SF_ENDIAN_LITTLE : SF_ENDIAN_BIG ;
   314	
   315	        while (! done)
   316	        {       size_t jump = chunk_size & 1 ;
   317	
   318	                marker = chunk_size = 0 ;
   319	                psf_binheader_readf (psf, "jm4", jump, &marker, &chunk_size) ;
   320	                if (marker == 0)
   321	                {       sf_count_t pos = psf_ftell (psf) ;
   322	                        psf_log_printf (psf, "Have 0 marker at position %D (0x%x).\n", pos, pos) ;
   323	                        break ;
   324	                        } ;
   325	
   326	                psf_store_read_chunk_u32 (&psf->rchunks, marker, psf_ftell (psf), chunk_size) ;
   327	
   328	                switch (marker)
   329	                {       case RIFF_MARKER :
   330	                        case RIFX_MARKER :
   331	                                        if (parsestage)
   332	                                                return SFE_WAV_NO_RIFF ;
   333	
   334	                                        parsestage |= HAVE_RIFF ;
   335	
   336	                                        RIFFsize = chunk_size ;
   337	
   338	                                        if (psf->fileoffset > 0 && psf->filelength > RIFFsize + 8)
   339	                                        {       /* Set file length. */
   340	                                                psf->filelength = RIFFsize + 8 ;
   341	                                                if (marker == RIFF_MARKER)
   342	                                                        psf_log_printf (psf, "RIFF : %u\n", RIFFsize) ;
   343	                                                else
   344	                                                        psf_log_printf (psf, "RIFX : %u\n", RIFFsize) ;
   345	                                                }
   346	                                        else if (psf->filelength < RIFFsize + 2 * SIGNED_SIZEOF (marker))
   347	                                        {       if (marker == RIFF_MARKER)
   348	                                                        psf_log_printf (psf, "RIFF : %u (should be %D)\n", RIFFsize, psf->filelength - 2 * SIGNED_SIZEOF (marker)) ;
   349	                                                else
   350	                                                        psf_log_printf (psf, "RIFX : %u (should be %D)\n", RIFFsize, psf->filelength - 2 * SIGNED_SIZEOF (marker)) ;
   351	
   352	                                                RIFFsize = psf->filelength - 2 * SIGNED_SIZEOF (RIFFsize) ;
   353	                                                }
   354	                                        else
   355	                                        {       if (marker == RIFF_MARKER)
   356	                                                        psf_log_printf (psf, "RIFF : %u\n", RIFFsize) ;
   357	                                                else
   358	                                                        psf_log_printf (psf, "RIFX : %u\n", RIFFsize) ;
   359	                                        } ;
   360	
   361	                                        psf_binheader_readf (psf, "m", &marker) ;
   362	                                        if (marker != WAVE_MARKER)
   363	                                                return SFE_WAV_NO_WAVE ;
   364	                                        parsestage |= HAVE_WAVE ;
   365	                                        psf_log_printf (psf, "WAVE\n") ;
   366	                                        chunk_size = 0 ;
   367	                                        break ;
   368	
   369	                        case fmt_MARKER :
   370	                                        if ((parsestage & (HAVE_RIFF | HAVE_WAVE)) != (HAVE_RIFF | HAVE_WAVE))
   371	                                                return SFE_WAV_NO_FMT ;
   372	
   373	                                        /* If this file has a SECOND fmt chunk, I don't want to know about it. */
   374	                                        if (parsestage & HAVE_fmt)
   375	                                                break ;
   376	
   377	                                        parsestage |= HAVE_fmt ;
   378	
   379	                                        psf_log_printf (psf, "fmt  : %d\n", chunk_size) ;
   380	
   381	                                        if ((error = wavlike_read_fmt_chunk (psf, chunk_size)))
   382	                                                return error ;
   383	
   384	                                        format = wav_fmt->format ;
   385	                                        break ;
   386	
   387	                        case data_MARKER :
   388	                                        if ((parsestage & (HAVE_RIFF | HAVE_WAVE | HAVE_fmt)) != (HAVE_RIFF | HAVE_WAVE | HAVE_fmt))
   389	                                                return SFE_WAV_NO_DATA ;
   390	
   391	                                        if (psf->file.mode == SFM_RDWR && (parsestage & HAVE_other) != 0)
   392	                                                return SFE_RDWR_BAD_HEADER ;
   393	
   394	                                        parsestage |= HAVE_data ;
   395	
   396	                                        psf->datalength = chunk_size ;
   397	                                        if (psf->datalength & 1)
   398	                                                psf_log_printf (psf, "*** 'data' chunk should be an even number of bytes in length.\n") ;
   399	
   400	                                        psf->dataoffset = psf_ftell (psf) ;
   401	
   402	                                        if (psf->dataoffset > 0)
   403	                                        {       if (chunk_size == 0 && RIFFsize == 8 && psf->filelength > 44)
   404	                                                {       psf_log_printf (psf, "*** Looks like a WAV file which wasn't closed properly. Fixing it.\n") ;
   405	                                                        psf->datalength = psf->filelength - psf->dataoffset ;
   406	                                                        } ;
   407	
   408	                                                if (psf->datalength > psf->filelength - psf->dataoffset)
   409	                                                {       psf_log_printf (psf, "data : %D (should be %D)\n", psf->datalength, psf->filelength - psf->dataoffset) ;
   410	                                                        psf->datalength = psf->filelength - psf->dataoffset ;
   411	                                                        }
   412	                                                else
   413	                                                        psf_log_printf (psf, "data : %D\n", psf->datalength) ;
   414	
   415	                                                /* Only set dataend if there really is data at the end. */
   416	                                                if (psf->datalength + psf->dataoffset < psf->filelength)
   417	                                                        psf->dataend = psf->datalength + psf->dataoffset ;
   418	
   419	                                                psf->datalength += chunk_size & 1 ;
   420	                                                chunk_size = 0 ;
   421	                                                } ;
   422	
   423	                                        if (! psf->sf.seekable || psf->dataoffset < 0)
   424	                                                break ;
   425	
   426	                                        /* Seek past data and continue reading header. */
   427	                                        psf_fseek (psf, psf->datalength, SEEK_CUR) ;
   428	
   429	                                        if (psf_ftell (psf) != psf->datalength + psf->dataoffset)
   430	                                                psf_log_printf (psf, "*** psf_fseek past end error ***\n") ;
   431	                                        break ;
   432	
   433	                        case fact_MARKER :
   434	                                        if ((parsestage & (HAVE_RIFF | HAVE_WAVE)) != (HAVE_RIFF | HAVE_WAVE))
   435	                                                return SFE_WAV_BAD_FACT ;
   436	
   437	                                        parsestage |= HAVE_fact ;
   438	
   439	                                        if ((parsestage & HAVE_fmt) != HAVE_fmt)
   440	                                                psf_log_printf (psf, "*** Should have 'fmt ' chunk before 'fact'\n") ;
   441	
   442	                                        psf_binheader_readf (psf, "4", & (fact_chunk.frames)) ;
   443	
   444	                                        if (chunk_size > SIGNED_SIZEOF (fact_chunk))
   445	                                                psf_binheader_readf (psf, "j", (int) (chunk_size - SIGNED_SIZEOF (fact_chunk))) ;
   446	
   447	                                        if (chunk_size)
   448	                                                psf_log_printf (psf, "%M : %u\n", marker, chunk_size) ;
   449	                                        else
   450	                                                psf_log_printf (psf, "%M : %u (should not be zero)\n", marker, chunk_size) ;
   451	
   452	                                        psf_log_printf (psf, "  frames  : %d\n", fact_chunk.frames) ;
   453	                                        break ;
   454	
   455	                        case PEAK_MARKER :
   456	                                        if ((parsestage & (HAVE_RIFF | HAVE_WAVE | HAVE_fmt)) != (HAVE_RIFF | HAVE_WAVE | HAVE_fmt))
   457	                                                return SFE_WAV_PEAK_B4_FMT ;
